from lib import *
S = SS('q5')
steps = [
    step("开启 confirm 模式(Confirm.Select,broker 回 SelectOk,两个 channel 各一次共 2 个帧)后,每条发布在 broker 那头都有一个从 1 开始递增的发布序号。pika 的 BlockingChannel 每发一条就等一条 ack,线上看到的 10 个 Basic.Ack 是 tag=1、2、…、10,multiple 全是 False——一条发布对应一个 Ack,没有任何合并。", t=tl(S(1)), mark=lidx(S(1), 'tag=1 ', 'tag=10 '), done=lidx(S(1), 'Confirm.Select'), kv=KV([['Confirm.Select', '把 channel 切成 confirm 模式'], ['发布序号', '每个 channel 从 1 递增'], ['同步发布', '一条一个 Basic.Ack,multiple=False']], ['发布序号'])),
    step("不等每一条,用 SelectConnection 一口气发 5000 条持久化消息(在途上限 1000):broker 共发回 619 个 Basic.Ack,其中 603 个是 multiple=True——它会把已处理好的一段连续序号合并成一个 Ack。每个 Ack 确认的条数最小 1、中位数 7、最大 73;前 8 个 Ack 分别确认了 29、33、12、11、6、15、7、3 条。发布方要按 multiple 处理,而不是假设一个 Ack 对一条。", t=tl(S(2)), mark=lidx(S(2), '每个 Ack 确认的条数'), done=lidx(S(2), '发 5000 条'), b=bars([['Ack 数', 619, '619 个'], ['multiple=True', 603, '603 个'], ['中位数条数/个', 7, '7 条'], ['最大条数/个', 73, '73 条']], 619, mark=[1], done=[0, 2, 3]), kv=KV([['multiple=True', '确认 ≤ tag 的所有未确认发布'], ['合并程度', '5000 条 → 619 个 Ack'], ['发布方', '必须按 multiple 维护在途集合']], ['multiple=True'])),
    step("四种发布方式的吞吐(5000 条 100 字节的持久化消息,各 3 次取中位数):每条同步等 confirm 要 869 ms(5752 条/秒);异步在途上限 100 是 92 ms(54057 条/秒),在途上限 1000 是 92 ms(54634 条/秒);不开 confirm 的阻塞连发是 132 ms。同步等的慢在于每条都要一次往返;只要允许几十条在途,吞吐就上去了,100 和 1000 没区别。(不开 confirm 一行和异步两行用的是 pika 不同的连接类型,不能互相比较。)", t=tl(S(3)), mark=lidx(S(3), '每条同步等 confirm'), done=lidx(S(3), '在途上限 100', '在途上限 1000', '不开 confirm(阻塞)'), b=bars([['每条同步等', 5752, '5752 条/秒'], ['在途上限 100', 54057, '54057 条/秒'], ['在途上限 1000', 54634, '54634 条/秒']], 54634, mark=[0], done=[1, 2]), kv=KV([['每条同步等', '869 ms / 5000 条'], ['异步在途 100', '92 ms'], ['区别', '同步一次往返 × 5000 次']], ['每条同步等'])),
    step("单条同步 confirm 的延迟(各 2000 条):非持久化消息 p50 = 0.08 ms、p99 = 0.15 ms;持久化消息 p50 = 0.15 ms、p99 = 0.26 ms。持久化的 p50 大约是非持久化的两倍。注意这个数字是在 macOS 上测的,而 macOS 的 fsync 并不保证落到盘片(要 F_FULLFSYNC),所以这里的“持久化延迟”远小于 Linux 服务器上真实 fsync 的代价。", t=tl(S(4)), mark=lidx(S(4), '持久化:p50'), done=lidx(S(4), '非持久化'), b=bars([['非持久化 p50', 0.08, '0.08 ms'], ['持久化 p50', 0.15, '0.15 ms'], ['非持久化 p99', 0.15, '0.15 ms'], ['持久化 p99', 0.26, '0.26 ms']], 0.26, mark=[1, 3], done=[0, 2]), kv=KV([['非持久化', 'p50 0.08 / p99 0.15 ms'], ['持久化', 'p50 0.15 / p99 0.26 ms'], ['平台', 'macOS 的 fsync 不等于 Linux 上的落盘']], ['平台'])),
    step("不可路由的消息:发到一个没有任何绑定的 exchange(mandatory=False),线上只有 Basic.Publish → Basic.Ack tag=1——broker 照样回 Ack,confirm 的含义是“broker 处理完了”,不是“进了某个队列”。加 mandatory=True 之后线上顺序是 Basic.Return(带内容头和内容体,把消息原样退回)→ Basic.Ack tag=2,pika 抛出 UnroutableError。Return 一定先于 Ack,所以收到 Ack 时已经知道有没有被退回。", t=tl(S(5)), mark=lidx(S(5), 'mandatory=True,线上帧'), done=lidx(S(5), 'mandatory=False'), kv=KV([['无绑定', '仍然 Ack'], ['mandatory=True', 'Basic.Return 先,Ack 后'], ['含义', 'Ack = 路由处理完,不等于入队']], ['无绑定'])),
    step("队列设 x-max-length=3、x-overflow=reject-publish,连发 5 条:前 3 条 Ack(tag=1、2、3),第 4、5 条收到 Basic.Nack(tag=4 和 tag=5,multiple 和 requeue 位在线上都是 1),pika 抛 NackError;队列里最终有 3 条。Nack 是 broker 明确说“这条我没收”,发布方可以据此重试或报错;不开 confirm 时这两条就是悄悄被拒、发布方无从知道。", t=tl(S(6)), mark=lidx(S(6), 'Basic.Nack', "['ack', 'ack', 'ack', 'NackError'"), done=lidx(S(6), '队列里最终有 3 条'), kv=KV([['reject-publish', '满了就 Nack 新发布的'], ['Nack', 'broker 明确拒收'], ['没开 confirm', '发布方不知道']], ['Nack'])),
]
A = mkartq('q5', 5, 'RabbitMQ,publisher confirms,Basic.Ack,multiple,mandatory,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上用 TCP 代理看发布确认:同步发布一条一个 Ack;异步发 5000 条 broker 合并成 619 个 Ack(603 个 multiple=True);每条同步等 5752 条/秒、在途上限 100 时 54057 条/秒;不可路由的消息也会被 Ack,mandatory 会先收到 Basic.Return;reject-publish 满队列时收到 Basic.Nack。',
    '发布者怎么知道 broker 收下了消息?confirm 模式下 Ack 一条一个还是批量?“确认”是指消息进了队列还是落了盘?队列满了会怎样?这篇用 TCP 代理把确认帧打出来,并比较几种发布方式的吞吐。',
    [('619 个', '异步发 5000 条消息时 broker 回的 Basic.Ack 个数(其中 603 个 multiple=True)'), ('5752 → 54057', '每条同步等 confirm 与异步在途上限 100 的吞吐(条/秒)'), ('Ack 但没入队', '发到没有绑定的 exchange 也会收到 Ack;mandatory=True 先 Return 后 Ack')],
    [('Confirm.Select 与序号', '<p><code>Confirm.Select</code> 把 channel 切成 confirm 模式,此后每条发布在该 channel 里有一个从 1 递增的序号,broker 用 <code>Basic.Ack</code>(成功)或 <code>Basic.Nack</code>(失败)按序号回复。</p>'),
     ('multiple', '<p>broker 可以把已处理好的一段序号合并成一个 <code>multiple=True</code> 的 Ack。异步发布时 5000 条只收到 619 个 Ack,中位数每个确认 7 条,所以发布方要维护一个“在途序号集合”,按 multiple 一次性清掉 ≤ tag 的部分。</p>'),
     ('吞吐', '<p>每发一条就等一个 Ack,吞吐受限于往返次数(5752 条/秒);允许几十条在途后升到 54057 条/秒,100 和 1000 没区别。因此一般做“窗口式”异步发布,而不是逐条等待。</p>'),
     ('延迟', '<p>单条同步 confirm 的 p50:非持久化 0.08 ms,持久化 0.15 ms。要说明的是,这是 macOS 笔记本上的数字,其 fsync 不保证落盘,不能当作生产环境的持久化延迟。</p>'),
     ('Ack 的含义', '<p>confirm 只说明 broker 处理完这条消息,不保证进了队列:没有绑定的 exchange 同样回 Ack。要知道有没有路由到队列,要加 <code>mandatory</code>,此时先收到 <code>Basic.Return</code> 再收到 Ack。</p>'),
     ('Nack', '<p>队列满且 <code>x-overflow=reject-publish</code> 时,新发布得到 <code>Basic.Nack</code>,发布方明确知道被拒;没开 confirm 就不知道。</p>')],
    steps,
    [ENV_Q + '。线上的 Ack / Nack 帧来自自己写的 TCP 代理;第二、三节异步发布用 pika SelectConnection(在途上限用已发送数减已确认数控制),同步用 BlockingChannel.confirm_delivery;吞吐是 5000 条 100 字节的持久化消息(delivery_mode=2)到持久队列的耗时,各 3 次取中位数;延迟各 2000 条',
     '没有验证:quorum 队列和 stream 队列的确认时机(多数派落盘之后才 Ack,见第 16 篇);Linux 上真实 fsync 的持久化延迟;跨节点集群里镜像或 quorum 的确认延迟;大消息体对 confirm 延迟的影响;在途窗口大于 1000 时的内存占用;连接中途断开时在途消息的结果不确定性'],
    '发布确认')
